#[test]
fn normalize_fuzz_seed_1_only_youtube_comes_out() {
    let mut rng = Rng::new(65537);
    for _ in 0..2000 {
        let text = rng.text(&["https://www.youtube.com/watch?v=", "youtu.be/", "music.youtube.com/", "https://", "dQw4w9WgXcQ"]);
        if let Some(url) = normalize(&text) {
            assert!(url.starts_with("https://www.youtube.com/") || url.starts_with("https://music.youtube.com/"), "{text:?} → {url}");
            assert_eq!(normalize(&url).as_deref(), Some(url.as_str()), "not idempotent: {text:?}");
        }
    }
}

